original_css_text_diff:
--- preimage
+++ postimage
@@ -43,6 +43,11 @@
 .dossier-section table { display: var(--layout-dossier-table); inline-size: var(--size-dossier-full); table-layout: fixed; border-collapse: collapse; margin-block: var(--space-12); }
 .dossier-section th, .dossier-section td { display: var(--layout-dossier-cell); padding: var(--space-9); border-block-end: var(--border-hairline) solid var(--color-line); text-align: start; vertical-align: top; min-inline-size: var(--space-0); }
 .dossier-section thead { background: var(--color-soft); }
+.dossier-section table[data-dossier-table="exclusions"] td:last-child > a,
+.dossier-section table[data-dossier-table="rejection-conditions"] td:last-child > a,
+.dossier-section table[data-dossier-table="rejection-conditions"] td:last-child > .technical-token {
+  display: block;
+}
 .dossier-record { margin-block: var(--space-9); }
 .dossier-record > div { border-block-end: var(--border-hairline) solid var(--color-line); padding-block: var(--space-7); }
 .dossier-record dt { color: var(--color-muted); font-weight: var(--font-weight-medium); }
@@ -78,6 +83,7 @@
   .page h1 { font-size: var(--font-size-dossier-print-title); }
   .page h2, .page h3 { break-after: avoid; }
   .dossier-intro { break-inside: avoid; }
+  .dossier-record .record-group > dt { break-after: avoid; }
   .rule-record > p:first-of-type { break-after: avoid; }
   .warning, .branch-disclosure { break-inside: avoid; }
   .dossier-section > .branch-label, .dossier-section > .branch-disclosure { break-after: avoid; }
